<section id="demo"><div class="sectionhead"><div><div class="eyebrow">02 / Reproducible evidence</div><h2>A missing ownership check. Real impact.</h2><p>Run a read-only check against this environment using a seeded lab account.</p></div></div><div class="demo"><div><h3>Horizontal privilege escalation</h3><p>Alice owns orders 1 and 2. Bob owns order 3. Authentication alone should never authorize Alice to read Bob's order.</p><ol class="dim"><li>Authenticate as Alice.</li><li>Request Alice's order as a positive control.</li><li>Request Bob's order with the same token.</li><li>Compare the response with the expected boundary.</li></ol><button class="btn primary" id="run">Run local check →</button><p class="note">Uses alice / <?= $mode === "vulnerable" ? "alice123" : "alice12345" ?>. No token is persisted. Response shown below is live, not a prerecorded result.</p></div><div class="demo-panel"><div class="eyebrow">Live response / <?= \Lab\Http::escape($mode) ?></div><pre id="evidence" role="status" aria-live="polite">Ready.
Run the check to collect evidence from this instance.</pre><button class="btn" id="download" disabled>Export evidence JSON ↓</button></div></div></section>
<script>
let artifact=null;const run=document.querySelector('#run'),evidence=document.querySelector('#evidence'),download=document.querySelector('#download');run.onclick=async()=>{run.disabled=true;download.disabled=true;artifact=null;evidence.textContent='Authenticating as Alice…';try{const login=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'alice',password:<?= json_encode($mode === "vulnerable" ? "alice123" : "alice12345") ?>})});if(!login.ok)throw Error('Login returned HTTP '+login.status);const auth=await login.json();const results=[];for(const id of [1,3]){const r=await fetch('/api/orders/'+id,{headers:{Authorization:'Bearer '+auth.access_token}});results.push({request:'GET /api/orders/'+id,status:r.status,body:await r.json()})}const control=results[0].status===200&&results[0].body.user_id===1;const observed=control?(results[1].status===200&&results[1].body.user_id===2?'EXPOSED':results[1].status===404?'BLOCKED':'INCONCLUSIVE'):'INCONCLUSIVE';artifact={finding:'VULN-01',environment:<?= json_encode($mode) ?>,captured_at:new Date().toISOString(),actor:'alice',control_passed:control,observed,results};evidence.textContent=JSON.stringify(artifact,null,2);download.disabled=false}catch(e){evidence.textContent='Check failed: '+e.message+'\nConfirm this local instance is running and seeded.'}finally{run.disabled=false}};download.onclick=()=>{if(!artifact)return;const u=URL.createObjectURL(new Blob([JSON.stringify(artifact,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='VULN-01-<?= \Lab\Http::escape($mode) ?>-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};

</script>
